import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'request_providers.dart';class RequestDetailScreen extends ConsumerWidget{const RequestDetailScreen({super.key,required this.id});final String id;@override Widget build(BuildContext c,WidgetRef r){final a=r.watch(requestDetailProvider(id));return Scaffold(appBar:AppBar(title:const Text('Request details')),body:a.when(data:(x)=>ListView(padding:const EdgeInsets.all(20),children:[Text(x.status,style:Theme.of(c).textTheme.titleLarge),if(x.service!=null)Text('Service: ${x.service!['title']??''}'),if(x.provider!=null)Text('Provider: ${x.provider!['user']?['name']??''}'),const Divider(),Text(x.message),const SizedBox(height:24),const Text('Timeline'),ListTile(title:Text('Created · ${x.createdAt?.toLocal().toString().split('.').first??''}')),ListTile(title:Text('Status · ${x.status}'))]),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e'))));}}
